function retornaUltimoDiaMes(data) {
  var mes = data.getMonth();
  var ano = data.getFullYear();

  mes++;

  if(mes > 11){
     mes = 0;
     ano ++;
  }

  var proximoMes = new Date(ano, mes, 1);
  var ultimoDia = new Date(proximoMes.getTime() - (1000 * 3600 * 24));

  return ultimoDia;
}

